    private void btnLoginActionPerformed(java.awt.event.ActionEvent evt) {                                         
        try {
            Connection c = koneksi.configDB();
            
            // Menggunakan PreparedStatement agar aman dari SQL Injection
            String sql = "SELECT * FROM users WHERE username = ? AND password = ?";
            PreparedStatement pst = c.prepareStatement(sql);
            
            pst.setString(1, txtUsername.getText());
            pst.setString(2, new String(txtPassword.getPassword())); // Cara aman mengambil password
            
            ResultSet r = pst.executeQuery();
            
            if (r.next()) {
                String role = r.getString("role");
                int idUser = r.getInt("id");
                
                if (role.equals("admin")) {
                    JOptionPane.showMessageDialog(this, "Login Berhasil sebagai Admin!");
                    new FormAdmin().setVisible(true);
                    this.dispose(); // Menutup form login
                } else if (role.equals("siswa")) {
                    JOptionPane.showMessageDialog(this, "Login Berhasil sebagai Siswa!");
                    new FormSiswa(idUser).setVisible(true);
                    this.dispose(); // Menutup form login
                }
            } else {
                JOptionPane.showMessageDialog(this, "Username atau Password salah!");
                txtPassword.setText("");
                txtUsername.requestFocus(); // Memindahkan kursor kembali ke kolom username
            }
        } catch (Exception e) {
            JOptionPane.showMessageDialog(this, "Terjadi kesalahan: " + e.getMessage());
        }
    }                                        

